"""run.py —— 单文件自释放入口。
双击运行后把内嵌的全部程序源文件释放到本文件所在目录（core/、ui/ 及根目录 .py）。
已存在的文件跳过、不覆盖（避免破坏你已有的本地修改）。
释放完成后双击 scanner_gui.py 即可运行主程序。
"""
from __future__ import annotations

import base64
import gzip
import os

# 内嵌文件：(相对路径, base64(gzip(内容)))
_FILES = [
    ('scanner_gui.py', ''),
    ('db_view.py', ''),
    ('core/__init__.py', 'H4sIAAAAAAACCgMAAAAAAAAAAAA='),
    ('core/analysis.py', ''),
    ('core/config.py', ''),
    ('core/exporter.py', ''),
    ('core/maintainer.py', ''),
    ('core/mic.py', ''),
    ('core/paths.py', ''),
    ('core/repo.py', ''),
    ('core/scanner.py', ''),
    ('core/single_instance.py', ''),
    ('ui/__init__.py', 'H4sIAAAAAAACCgMAAAAAAAAAAAA='),
    ('ui/main_window.py', ''),
    ('ui/task_center.py', ''),
    ('ui/tray.py', ''),
    ('ui/widgets.py', ''),
]


def _release(target_dir):
    """把内嵌文件释放到 target_dir；已存在的同名文件跳过、不覆盖。

    返回 (新建列表, 跳过列表, 失败列表[(路径, 原因)])。
    """
    created, skipped, failed = [], [], []
    for rel, b64 in _FILES:
        dest = os.path.join(target_dir, rel)
        parent = os.path.dirname(dest)
        if parent and not os.path.isdir(parent):
            os.makedirs(parent, exist_ok=True)
        # 已存在则跳过，避免破坏目标机器上可能已有的本地修改
        if os.path.exists(dest):
            skipped.append(rel)
            continue
        try:
            with open(dest, "wb") as f:
                f.write(gzip.decompress(base64.b64decode(b64)))
        except OSError as e:
            # 写入失败（如目录不可写）时跳过该文件，不让整个释放中断
            failed.append((rel, str(e)))
            continue
        created.append(rel)
    return created, skipped, failed


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    created, skipped, failed = _release(here)
    print("[release] 释放目录：%s" % here)
    if created:
        print("[release] 新建 %d 个文件：" % len(created))
        for r in created:
            print("  + " + r)
    if skipped:
        print("[release] 跳过 %d 个已存在的文件（未覆盖）：" % len(skipped))
        for r in skipped:
            print("  - " + r)
    if failed:
        print("[release] %d 个文件写入失败：" % len(failed))
        for r, err in failed:
            print("  ! %s (%s)" % (r, err))
    if created and not failed:
        print("[release] 完成，双击 scanner_gui.py 即可运行主程序。")
    elif not created and not failed:
        print("[release] 所有程序文件已存在，未做任何覆盖。")
        print("如需强制替换为本 run.py 内嵌的版本：删除同目录下的 core/、ui/ 及根目录 .py 后重新运行。")
        print("双击 scanner_gui.py 即可运行主程序。")


if __name__ == "__main__":
    main()
